import { format, resolveConfig } from 'prettier';
import type { KnowledgeChunk } from '../../libs/core/src/ask/entities/knowledge-chunk.js';
import { KnowledgeSourceKind } from '../../libs/core/src/ask/enums/knowledge-source-kind.enum.js';

const HEADER = [
  "// Generated by `pnpm knowledge:build` from crossmart-docs and crossmart.io's llms.txt.",
  '// Do not edit by hand; see docs/ask-crossmart.md to refresh it.',
  "import type { KnowledgeChunk } from '../entities/knowledge-chunk.js';",
  "import { KnowledgeSourceKind } from '../enums/knowledge-source-kind.enum.js';",
  '',
].join('\n');
const SOURCE_MEMBERS: Record<KnowledgeSourceKind, string> = {
  [KnowledgeSourceKind.Docs]: 'KnowledgeSourceKind.Docs',
  [KnowledgeSourceKind.Site]: 'KnowledgeSourceKind.Site',
  [KnowledgeSourceKind.Plans]: 'KnowledgeSourceKind.Plans',
};
const JSON_INDENTATION = 2;

function chunkLiteral(chunk: KnowledgeChunk): string {
  const fields = [
    `id: ${JSON.stringify(chunk.id)}`,
    `source: ${SOURCE_MEMBERS[chunk.source]}`,
    `title: ${JSON.stringify(chunk.title)}`,
    `url: ${JSON.stringify(chunk.url)}`,
    `text: ${JSON.stringify(chunk.text, null, JSON_INDENTATION)}`,
  ];
  return `{ ${fields.join(', ')} }`;
}

/** The generated TypeScript module, formatted as Prettier would, so `pnpm format` keeps it. */
export async function renderModule(
  chunks: readonly KnowledgeChunk[],
  filePath: string,
): Promise<string> {
  const body = `export const DOCS_KNOWLEDGE_CHUNKS: readonly KnowledgeChunk[] = [${chunks
    .map(chunkLiteral)
    .join(',\n')}];\n`;
  const options = (await resolveConfig(filePath)) ?? {};
  return format(`${HEADER}\n${body}`, { ...options, filepath: filePath });
}
